from collections import deque
def solve(g):
    H,W=len(g),len(g[0])
    # exterior zero map
    ext=[[False]*W for _ in range(H)]
    q=deque([(x,y) for x in range(H) for y in (0,W-1) if g[x][y]==0] +
            [(x,y) for y in range(W) for x in (0,H-1) if g[x][y]==0])
    while q:
        a,b=q.popleft()
        for da in(-1,0,1):
            for db in(-1,0,1):
                x,y=a+da,b+db
                if 0<=x<H and 0<=y<W and not ext[x][y] and g[x][y]==0:
                    ext[x][y]=True; q.append((x,y))
    seen=[[False]*W for _ in g]; objs=[]
    for i in range(H):
        for j in range(W):
            if not seen[i][j] and g[i][j]:
                v=g[i][j]; st=[(i,j)]; seen[i][j]=True; cells=[]
                while st:
                    a,b=st.pop(); cells.append((a,b))
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            x,y=a+da,b+db
                            if 0<=x<H and 0<=y<W and not seen[x][y] and g[x][y]==v:
                                seen[x][y]=True; st.append((x,y))
                r0=min(r for r,_ in cells); c0=min(c for _,c in cells)
                rel=[(r-r0,c-c0) for r,c in cells]
                h=max(r for r,_ in rel)+1; w_=max(c for _,c in rel)+1
                # enclosed holes = zero cells inside bbox not reachable from bbox border through zeros
                hole=set()
                dq=deque()
                for ii in range(h):
                    for jj in (0,w_-1):
                        if g[r0+ii][c0+jj]==0 and not ext.get((r0+ii,c0+jj),False): hole.add((ii,jj)); dq.append((ii,jj))
                for jj in range(w_):
                    for ii in (0,h-1):
                        if g[r0+ii][c0+jj]==0 and not ext.get((r0+ii,c0+jj),False) and (ii,jj) not in hole: hole.add((ii,jj)); dq.append((ii,jj))
                while dq:
                    a,b=dq.popleft()
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            x,y=a+da,b+db
                            if 0<=x<h and 0<=y<w_ and (x,y) not in hole and g[r0+x][c0+y]==0:
                                hole.add((x,y)); dq.append((x,y))
                dr=-1 if hole else 1
                nr=r0; placed=set()
                while True:
                    nxt=nr+dr
                    if not all(0<=nxt+p<H and 0<=cc+W for p,cc in rel): break
                    if any((nxt+p,cc+c0) in placed for p,cc in rel): break
                    nr=nxt
                    placed.update((nr+p,cc+c0) for p,cc in rel)
                target={(nr+p,cc+c0) for p,cc in rel}
                objs.append({'v':v,'target':target})
    out=[[0]*W for _ in range(H)]
    for o in objs:
        for (r,c),v in zip(o['target'],None): pass
    return out

